/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { lineFromRequest } from './src/api.js';
import { parseQuantity as apiQuantity } from './src/quantity.js';
import { parseQuantity as cliQuantity } from './src/cli.js';

const zeroResult = lineFromRequest({ sku: ' A ', quantity: '0' });
assert.deepEqual(zeroResult, { sku: 'A', quantity: 0, active: false });
assert.deepEqual(lineFromRequest({ sku: ' A ', quantity: 0 }), zeroResult);
assert.equal(apiQuantity(' 0 '), 0);
for (const [value, expected] of [[1, 1], [42, 42], ['1', 1], [' 7 ', 7], ['2.0', 2], [[1], 1]]) {
  assert.equal(apiQuantity(value), expected);
  assert.equal(lineFromRequest({ sku: 'A', quantity: value }).active, true);
}
const invalid = [-1, '-1', -0.5, 0.5, '1.5', NaN, Infinity, -Infinity, 'Infinity', '', ' ', '\\t\\n', true, false, null, undefined, 'not a number', [], [0]];
let errorMessage;
for (const value of invalid) {
  assert.throws(() => lineFromRequest({ sku: 'A', quantity: value }), (error) => {
    assert.equal(error.constructor, Error);
    assert.equal(error.message, 'invalid quantity');
    errorMessage = error.message;
    return true;
  });
}
assert.equal(cliQuantity('0'), 1);
assert.equal(cliQuantity('12abc'), 12);
assert.equal(cliQuantity('-2'), -2);
const answer = { changed_file: 'src/quantity.js', zero_result: zeroResult, error_message: errorMessage };
writeFileSync('answer.json', JSON.stringify(answer, null, 2) + '\\n');
console.log(JSON.stringify({ check: 'passed', positive_cases: 6, rejected_cases: invalid.length, cli_legacy_checks: 3, answer }));
NODE"

